package reliability

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

const (
	sessionSchemaVersion = 1
	// sessionFilePrefix/sessionFileSuffix wrap a base64url-encoded session ID.
	// IDs are generated by StableID and contain "/" (e.g. "sess/abc123"), so
	// they cannot be used as file names directly. The prefix also keeps the
	// name away from Windows device names (CON, NUL, ...).
	sessionFilePrefix = "session-"
	sessionFileSuffix = ".json"
	// maxSessionIDBytes bounds the base64url-encoded file name (4/3 growth,
	// plus prefix/suffix) below the conventional 255-byte limit.
	maxSessionIDBytes = 128
)

// SessionStore persists research sessions so a STALLED/PARKED/HANDOFF session
// can resume across processes. The reliability layer's in-memory state remains
// the working copy; the store is the recovery point.
type SessionStore interface {
	Save(ctx context.Context, session *ResearchSession) error
	Load(ctx context.Context, id string) (*ResearchSession, error)
	List(ctx context.Context) ([]string, error)
}

// FileSessionStore stores one JSON file per session under Dir. Writes are
// atomic (temp file + rename) and 0600.
type FileSessionStore struct {
	Dir string
}

type sessionEnvelope struct {
	Version  int             `json:"version"`
	Revision uint64          `json:"revision"`
	SavedAt  time.Time       `json:"saved_at"`
	Session  ResearchSession `json:"session"`
}

func NewFileSessionStore(dir string) (*FileSessionStore, error) {
	dir = strings.TrimSpace(dir)
	if dir == "" {
		return nil, fmt.Errorf("reliability: session store directory is empty")
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil, fmt.Errorf("reliability: create session store %s: %w", dir, err)
	}
	return &FileSessionStore{Dir: dir}, nil
}

func (s *FileSessionStore) Save(ctx context.Context, session *ResearchSession) error {
	if err := contextErr(ctx); err != nil {
		return err
	}
	if s == nil || strings.TrimSpace(s.Dir) == "" {
		return fmt.Errorf("reliability: session store is not configured")
	}
	if err := session.Validate(); err != nil {
		return err
	}
	path, err := s.path(session.ID)
	if err != nil {
		return err
	}
	return s.withLock(ctx, path, func() error {
		return s.saveLocked(session, path)
	})
}

// saveLocked performs a revision CAS and atomic replace while holding the
// per-session writer lock.
func (s *FileSessionStore) saveLocked(session *ResearchSession, path string) error {
	next := session.Revision + 1
	raw, err := os.ReadFile(path)
	switch {
	case err == nil:
		var env sessionEnvelope
		if err := json.Unmarshal(raw, &env); err != nil {
			return fmt.Errorf("reliability: decode existing session %s: %w", session.ID, err)
		}
		if env.Version != sessionSchemaVersion {
			return fmt.Errorf("reliability: session %s has unsupported version %d", session.ID, env.Version)
		}
		if env.Session.ID != session.ID {
			return fmt.Errorf("reliability: session %s file contains id %s", session.ID, env.Session.ID)
		}
		if env.Revision != session.Revision {
			return fmt.Errorf("%w: session %s revision %d, file has %d",
				ErrSessionConflict, session.ID, session.Revision, env.Revision)
		}
	case errors.Is(err, os.ErrNotExist):
		if session.Revision != 0 {
			return fmt.Errorf("%w: session %s revision %d but no file exists",
				ErrSessionConflict, session.ID, session.Revision)
		}
	default:
		return fmt.Errorf("reliability: read existing session %s: %w", session.ID, err)
	}

	// Marshal a copy whose embedded Revision already matches the envelope. The
	// live session is only advanced after the rename commits, so a failed write
	// does not make the in-memory revision look saved.
	snapshot := *session
	snapshot.Revision = next
	payload, err := json.MarshalIndent(sessionEnvelope{
		Version: sessionSchemaVersion, Revision: next, SavedAt: time.Now().UTC(), Session: snapshot,
	}, "", "  ")
	if err != nil {
		return fmt.Errorf("reliability: marshal session %s: %w", session.ID, err)
	}
	tmp, err := os.CreateTemp(s.Dir, ".session-*.tmp")
	if err != nil {
		return fmt.Errorf("reliability: create session temp file: %w", err)
	}
	tmpName := tmp.Name()
	defer func() { _ = os.Remove(tmpName) }()
	if _, err := tmp.Write(payload); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("reliability: write session temp file: %w", err)
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("reliability: sync session temp file: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("reliability: close session temp file: %w", err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return fmt.Errorf("reliability: commit session %s: %w", session.ID, err)
	}
	// Best-effort directory sync; directory fsync is not supported everywhere
	// (notably Windows), so a failure here does not undo a committed rename.
	if dir, err := os.Open(s.Dir); err == nil {
		_ = dir.Sync()
		_ = dir.Close()
	}
	session.Revision = next
	return nil
}

const sessionLockSuffix = ".lock"

// withLock serializes writers for one session. The lock is an OS advisory lock
// on a stable lock file:
//
//   - the kernel releases it when the holder closes the file or dies, so a
//     crash needs no age-based "stale lock" breaking;
//   - mtime is never used to steal a lock, which removes the TOCTOU race where
//     two recovering writers could delete each other's fresh lock and both
//     enter the revision CAS;
//   - the lock file itself is left in place. Removing it after unlock would let
//     two processes lock different inodes at the same path.
//
// The read-compare-write CAS in saveLocked still runs under this lock, so only
// one writer can observe revision N and commit N+1.
func (s *FileSessionStore) withLock(ctx context.Context, path string, fn func() error) error {
	if ctx == nil {
		ctx = context.Background()
	}
	lockPath := path + sessionLockSuffix
	f, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return fmt.Errorf("reliability: open session lock: %w", err)
	}
	defer func() { _ = f.Close() }()

	waitCtx := ctx
	if _, ok := ctx.Deadline(); !ok {
		var cancel context.CancelFunc
		waitCtx, cancel = context.WithTimeout(ctx, 30*time.Second)
		defer cancel()
	}
	for {
		locked, err := tryLockFile(f)
		if err != nil {
			return fmt.Errorf("reliability: acquire session lock: %w", err)
		}
		if locked {
			defer func() { _ = unlockFile(f) }()
			return fn()
		}
		select {
		case <-waitCtx.Done():
			return fmt.Errorf("reliability: wait for session lock: %w", waitCtx.Err())
		case <-time.After(20 * time.Millisecond):
		}
	}
}

func (s *FileSessionStore) Load(ctx context.Context, id string) (*ResearchSession, error) {
	if err := contextErr(ctx); err != nil {
		return nil, err
	}
	if s == nil || strings.TrimSpace(s.Dir) == "" {
		return nil, fmt.Errorf("reliability: session store is not configured")
	}
	path, err := s.path(id)
	if err != nil {
		return nil, err
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, fmt.Errorf("%w: session %s", ErrNotFound, id)
		}
		return nil, fmt.Errorf("reliability: read session %s: %w", id, err)
	}
	var env sessionEnvelope
	if err := json.Unmarshal(raw, &env); err != nil {
		return nil, fmt.Errorf("reliability: decode session %s: %w", id, err)
	}
	if env.Version != sessionSchemaVersion {
		return nil, fmt.Errorf("reliability: session %s has unsupported version %d", id, env.Version)
	}
	if env.Session.ID != id {
		return nil, fmt.Errorf("reliability: session %s contains id %s", id, env.Session.ID)
	}
	if err := env.Session.Validate(); err != nil {
		return nil, err
	}
	session := env.Session
	session.Revision = env.Revision
	return &session, nil
}

func (s *FileSessionStore) List(ctx context.Context) ([]string, error) {
	if err := contextErr(ctx); err != nil {
		return nil, err
	}
	if s == nil || strings.TrimSpace(s.Dir) == "" {
		return nil, fmt.Errorf("reliability: session store is not configured")
	}
	entries, err := os.ReadDir(s.Dir)
	if err != nil {
		return nil, fmt.Errorf("reliability: list sessions: %w", err)
	}
	var out []string
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		id, ok := decodeSessionFileName(entry.Name())
		if !ok {
			continue
		}
		out = append(out, id)
	}
	sort.Strings(out)
	return out, nil
}

func (s *FileSessionStore) path(id string) (string, error) {
	if id == "" {
		return "", fmt.Errorf("reliability: invalid session id %q", id)
	}
	if id != strings.TrimSpace(id) {
		return "", fmt.Errorf("reliability: session id has surrounding whitespace")
	}
	if strings.ContainsRune(id, 0) {
		return "", fmt.Errorf("reliability: session id contains NUL")
	}
	if len(id) > maxSessionIDBytes {
		return "", fmt.Errorf("reliability: session id is too long (%d bytes)", len(id))
	}
	name := sessionFilePrefix + base64.RawURLEncoding.EncodeToString([]byte(id)) + sessionFileSuffix
	return filepath.Join(s.Dir, name), nil
}

func decodeSessionFileName(name string) (string, bool) {
	if !strings.HasPrefix(name, sessionFilePrefix) || !strings.HasSuffix(name, sessionFileSuffix) {
		return "", false
	}
	encoded := strings.TrimSuffix(strings.TrimPrefix(name, sessionFilePrefix), sessionFileSuffix)
	raw, err := base64.RawURLEncoding.DecodeString(encoded)
	if err != nil || len(raw) == 0 {
		return "", false
	}
	return string(raw), true
}

// ErrNotFound is returned when a persisted session does not exist.
var ErrNotFound = errors.New("reliability: not found")

// ErrSessionConflict means the in-memory session revision is older than the
// persisted revision. The caller must reload and reapply its changes instead
// of overwriting a newer snapshot.
var ErrSessionConflict = errors.New("reliability: session revision conflict")

func contextErr(ctx context.Context) error {
	if ctx == nil {
		return nil
	}
	return ctx.Err()
}
